adcs_vec3_t zero = {0.0, 0.0, 0.0};
adcs_vec3_t req, req_abs;
double stop_th;
double on_th;
int all_below;
int valid;

mp_output.realized_a_m2 = zero;

/* ---- validation ---- */
valid = 1;
if ((mp_input.enable != 0) && (mp_input.enable != 1)) valid = 0;
if (mp_input.field_body_t == NULL) valid = 0;
if (mp_input.request_a_m2 == NULL) valid = 0;
if (!(mp_config.max_dipole_a_m2 > 0.0)) valid = 0;
if (!(mp_config.stop_fraction > 0.0)) valid = 0;
if (!(mp_config.start_fraction > mp_config.stop_fraction)) valid = 0;
if (!(mp_config.start_fraction <= 1.0)) valid = 0;
if (mp_config.pulse_cycles < 1U || mp_config.pulse_cycles > 100U) valid = 0;
if (mp_config.cooldown_cycles < 1U || mp_config.cooldown_cycles > 100U) valid = 0;
if (mp_config.reversal_blank_cycles < 1U || mp_config.reversal_blank_cycles > 100U) valid = 0;
if (mp_config.max_thermal_cycles < 1U || mp_config.max_thermal_cycles > 100U) valid = 0;
if (mp_config.recovery_cycles < 1U || mp_config.recovery_cycles > 100U) valid = 0;
if (valid && !adcs_is_finite_vec3(mp_input.field_body_t)) valid = 0;
if (valid && !adcs_is_finite_vec3(mp_input.request_a_m2)) valid = 0;
if (valid && adcs_vec3_norm(mp_input.field_body_t) <= 1.0e-12) valid = 0;
if (valid && adcs_vec3_norm(mp_input.request_a_m2) <= 1.0e-12) valid = 0;

if (!valid && mp_input.enable) {
    mp_state.mode = MP_FAULT;
    mp_state.elapsed = 0U;
}

/* ---- FAULT latch ---- */
if (mp_state.mode == MP_FAULT) {
    if (!mp_input.enable) {
        mp_state.mode = MP_IDLE;
        mp_state.elapsed = 0U;
        mp_state.thermal_cycles = 0U;
        mp_state.recovery_count = 0U;
        mp_state.captured_a_m2 = zero;
        mp_state.last_capture_a_m2 = zero;
    }
    mp_output.mode = mp_state.mode;
    mp_output.elapsed = mp_state.elapsed;
    mp_output.thermal_cycles = mp_state.thermal_cycles;
    mp_output.recovery_count = mp_state.recovery_count;
    mp_output.realized_a_m2 = zero;
    mp_output.torque_nm = adcs_vec3_cross(&zero, mp_input.field_body_t);
    return;
}

/* ---- Disable clears all state ---- */
if (!mp_input.enable) {
    mp_state.mode = MP_IDLE;
    mp_state.elapsed = 0U;
    mp_state.thermal_cycles = 0U;
    mp_state.recovery_count = 0U;
    mp_state.captured_a_m2 = zero;
    mp_state.last_capture_a_m2 = zero;
    mp_output.mode = mp_state.mode;
    mp_output.elapsed = mp_state.elapsed;
    mp_output.thermal_cycles = mp_state.thermal_cycles;
    mp_output.recovery_count = mp_state.recovery_count;
    mp_output.realized_a_m2 = zero;
    mp_output.torque_nm = adcs_vec3_cross(&zero, mp_input.field_body_t);
    return;
}

req = *mp_input.request_a_m2;
stop_th = mp_config.stop_fraction * mp_config.max_dipole_a_m2;
on_th = mp_config.start_fraction * mp_config.max_dipole_a_m2;
req_abs = (adcs_vec3_t){fabs(req.x), fabs(req.y), fabs(req.z)};
all_below = (req_abs.x < stop_th) && (req_abs.y < stop_th) && (req_abs.z < stop_th);

switch (mp_state.mode) {
case MP_IDLE: {
    adcs_vec3_t cap = {0.0, 0.0, 0.0};
    int had = 0;
    int oppose = 0;
    double lx = mp_state.last_capture_a_m2.x;
    double ly = mp_state.last_capture_a_m2.y;
    double lz = mp_state.last_capture_a_m2.z;

    /* axis x */
    if (lx != 0.0 && ((req.x > 0.0) == (lx > 0.0))) {
        if (fabs(req.x) >= stop_th) { cap.x = (req.x > 0.0) ? mp_config.max_dipole_a_m2 : -mp_config.max_dipole_a_m2; had = 1; }
    } else {
        if (fabs(req.x) >= on_th) { cap.x = (req.x > 0.0) ? mp_config.max_dipole_a_m2 : -mp_config.max_dipole_a_m2; had = 1; }
    }
    /* axis y */
    if (ly != 0.0 && ((req.y > 0.0) == (ly > 0.0))) {
        if (fabs(req.y) >= stop_th) { cap.y = (req.y > 0.0) ? mp_config.max_dipole_a_m2 : -mp_config.max_dipole_a_m2; had = 1; }
    } else {
        if (fabs(req.y) >= on_th) { cap.y = (req.y > 0.0) ? mp_config.max_dipole_a_m2 : -mp_config.max_dipole_a_m2; had = 1; }
    }
    /* axis z */
    if (lz != 0.0 && ((req.z > 0.0) == (lz > 0.0))) {
        if (fabs(req.z) >= stop_th) { cap.z = (req.z > 0.0) ? mp_config.max_dipole_a_m2 : -mp_config.max_dipole_a_m2; had = 1; }
    } else {
        if (fabs(req.z) >= on_th) { cap.z = (req.z > 0.0) ? mp_config.max_dipole_a_m2 : -mp_config.max_dipole_a_m2; had = 1; }
    }

    if (!had) {
        /* stay IDLE, emit zero */
        mp_output.realized_a_m2 = zero;
    } else {
        if (lx != 0.0 && cap.x != 0.0 && ((cap.x > 0.0) != (lx > 0.0))) oppose = 1;
        if (ly != 0.0 && cap.y != 0.0 && ((cap.y > 0.0) != (ly > 0.0))) oppose = 1;
        if (lz != 0.0 && cap.z != 0.0 && ((cap.z > 0.0) != (lz > 0.0))) oppose = 1;

        mp_state.captured_a_m2 = cap;
        if (oppose) {
            mp_state.mode = MP_REVERSAL_WAIT;
            mp_state.elapsed = 0U;
            mp_state.last_capture_a_m2 = zero;
            mp_output.realized_a_m2 = zero;
        } else {
            mp_state.mode = MP_PULSE;
            mp_state.elapsed = 1U;
            mp_state.thermal_cycles += 1U;
            mp_state.last_capture_a_m2 = cap;
            mp_output.realized_a_m2 = cap;
            if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
                mp_state.mode = MP_INHIBIT;
                mp_output.realized_a_m2 = zero;
            }
        }
    }
    break;
}
case MP_PULSE: {
    if (all_below) {
        mp_state.mode = MP_COOLDOWN;
        mp_state.elapsed = 0U;
        mp_output.realized_a_m2 = zero;
    } else {
        mp_state.elapsed += 1U;
        mp_state.thermal_cycles += 1U;
        mp_state.last_capture_a_m2 = mp_state.captured_a_m2;
        mp_output.realized_a_m2 = mp_state.captured_a_m2;
        if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
            mp_state.mode = MP_INHIBIT;
            mp_output.realized_a_m2 = zero;
        } else if (mp_state.elapsed >= mp_config.pulse_cycles) {
            mp_state.mode = MP_COOLDOWN;
            mp_state.elapsed = 0U;
        }
    }
    break;
}
case MP_COOLDOWN: {
    mp_output.realized_a_m2 = zero;
    mp_state.elapsed += 1U;
    if (mp_state.elapsed >= mp_config.cooldown_cycles) {
        mp_state.mode = MP_IDLE;
        mp_state.elapsed = 0U;
    }
    break;
}
case MP_REVERSAL_WAIT: {
    mp_output.realized_a_m2 = zero;
    mp_state.elapsed += 1U;
    if (mp_state.elapsed >= mp_config.reversal_blank_cycles) {
        mp_state.mode = MP_IDLE;
        mp_state.elapsed = 0U;
        mp_state.last_capture_a_m2 = zero;
    }
    break;
}
case MP_INHIBIT: {
    mp_output.realized_a_m2 = zero;
    if (all_below) {
        mp_state.recovery_count += 1U;
    } else {
        mp_state.recovery_count = 0U;
    }
    if (mp_state.recovery_count >= mp_config.recovery_cycles) {
        mp_state.mode = MP_IDLE;
        mp_state.elapsed = 0U;
        mp_state.thermal_cycles = 0U;
        mp_state.recovery_count = 0U;
    }
    break;
}
default:
    mp_state.mode = MP_IDLE;
    mp_state.elapsed = 0U;
    mp_output.realized_a_m2 = zero;
    break;
}

mp_output.mode = mp_state.mode;
mp_output.elapsed = mp_state.elapsed;
mp_output.thermal_cycles = mp_state.thermal_cycles;
mp_output.recovery_count = mp_state.recovery_count;
mp_output.torque_nm = adcs_vec3_cross(&mp_output.realized_a_m2, mp_input.field_body_t);

